{
    "name": "detain/myadmin-powerdns",
    "type": "myadmin-plugin",
    "description": "PowerDNS DNS management plugin for the MyAdmin control panel, providing domain hosting, record management, and reverse DNS functionality through a PowerDNS backend.",
    "keywords": [
        "dns",
        "powerdns",
        "domain",
        "myadmin",
        "plugin",
        "nameserver",
        "reverse-dns"
    ],
    "license": "LGPL-2.1-only",
    "authors": [
        {
            "name": "Joe Huss",
            "homepage": "https://my.interserver.net/"
        }
    ],
    "config": {
        "bin-dir": "vendor/bin",
        "minimum-stability": "dev",
        "allow-plugins": {
            "detain/myadmin-plugin-installer": true
        }
    },
    "require": {
        "php": ">=5.0.0",
        "symfony/event-dispatcher": "*@stable",
        "detain/myadmin-plugin-installer": "dev-master"
    },
    "require-dev": {
        "phpunit/phpunit": "^9.6"
    },
    "autoload": {
        "psr-4": {
            "Detain\\MyAdminPowerDns\\": "src/"
        }
    },
    "autoload-dev": {
        "psr-4": {
            "Detain\\MyAdminPowerDns\\Tests\\": "tests/"
        }
    }
}

#!/usr/bin/env php
<?php
    $_SERVER['HTTP_HOST'] = 'my.interserver.net';

    require_once __DIR__.'/../../../../include/functions.inc.php';

    $db = clone $GLOBALS['tf']->db;
    $db->query("select history_owner, history_new_value from history_log where history_type='dns_manager' and history_new_value like '%new%'");
    while ($db->next_record(MYSQL_ASSOC)) {
        $data = myadmin_unstringify($db->Record['history_new_value']);
        if ($data['new'] == 1 && valid_domain($data['domain'])) {
            echo "update domains set account={$db->Record['history_owner']} where name='".$data['domain']."';\n";
        }
    }

#!/usr/bin/env php
<?php

    require_once __DIR__.'/../../../../include/console.functions.inc.php';
    global $console;
    if ($_SERVER['argc'] != 4 && $_SERVER['argc'] != 3) {
        echo "$console[WHITE]Usage: $console[LIGHTCYAN]" . $_SERVER['argv'][0] . "$console[WHITE] <$console[LIGHTPURPLE]account$console[WHITE]> <$console[LIGHTPURPLE]domain$console[WHITE]> <$console[LIGHTPURPLE]ip$console[WHITE]> [$console[BROWN]confirm$console[WHITE]]\n";
        exit;
    }

    $account = $_SERVER['argv'][1];
    $dns_domain = $_SERVER['argv'][2];
    $dns_ip = $_SERVER['argv'][3];

    require_once __DIR__.'/../../../../include/functions.inc.php';

    function_requirements('add_dns_domain');
    $custid = $GLOBALS['tf']->accounts->cross_reference($account);
    $webpage = false;
    define('VERBOSE_MODE', false);
    $GLOBALS['tf']->session->create($custid, 'admin');
    $sid = $GLOBALS['tf']->session->sessionid;
    function_requirements('add_dns_domain');
    print_r(add_dns_domain($dns_domain, $dns_ip));
    $GLOBALS['tf']->session->destroy();

echo 'for i in $(echo "select name from domains;" | mysql -s pdns); do
echo -n "$i						";
pdns_control notify $i ;
done' | ssh root@cdns1.interserver.net
